# helper forecasts h steps, return array h
def seasonal_naive(train,h):
    idx = pd.date_range(train.index[-1]+pd.offsets.MonthBegin(1), periods=h, freq='MS')
    vals=[]
    for d in idx:
        prev=d-pd.DateOffset(years=1)
        vals.append(train.loc[prev] if prev in train.index else train.iloc[-1])
    return np.array(vals)

def last_obs(train,h): return np.repeat(train.iloc[-1], h)

def ma3(train,h): return np.repeat(train.tail(3).mean(), h)

def snaive_yoy_adj(train,h):
    # last-year same month multiplied by avg YoY ratio over last 3 months where prior year exists
    idx = pd.date_range(train.index[-1]+pd.offsets.MonthBegin(1), periods=h, freq='MS')
    ratios=[]
    for d in train.tail(6).index:
        py=d-pd.DateOffset(years=1)
        if py in train.index and train.loc[py]>0:
            ratios.append(train.loc[d]/train.loc[py])
    ratio=np.median(ratios[-3:]) if ratios else 1.0
    vals=[]
    for d in idx:
        prev=d-pd.DateOffset(years=1)
        base=train.loc[prev] if prev in train.index else train.iloc[-1]
        vals.append(base*ratio)
    return np.array(vals)

def ets_forecast(train,h):
    # robust choices depending length
    model = ExponentialSmoothing(train, trend='add', damped_trend=True, seasonal='add', seasonal_periods=12, initialization_method='estimated')
    fit = model.fit(optimized=True, use_brute=True)
    return fit.forecast(h).values

def ets_mul_log_forecast(train,h):
    logt=np.log(train)
    model=ExponentialSmoothing(logt, trend='add', damped_trend=True, seasonal='add', seasonal_periods=12, initialization_method='estimated')
    fit=model.fit(optimized=True, use_brute=True)
    return np.exp(fit.forecast(h).values)

def sarimax_log_forecast(train,h):
    logt=np.log(train)
    # simple seasonal ARIMA; more stable than free auto on 39 obs
    best=None
    specs=[]
    for order in [(0,1,1),(1,1,0),(1,0,0),(0,1,0),(1,1,1)]:
        for seas in [(0,1,1,12),(1,0,0,12),(0,0,0,12)]:
            try:
                fit=SARIMAX(logt, order=order, seasonal_order=seas, trend='c' if order[1]==0 and seas[1]==0 else 'n', enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=200)
                specs.append((fit.aic, order, seas, fit))
            except Exception as e: pass
    specs=sorted(specs, key=lambda x:x[0])
    fit=specs[0][3]
    fc=fit.get_forecast(h).predicted_mean
    return np.exp(fc.values)

